const pinHash = bcrypt.hashSync('changeme', 10);
db.prepare('INSERT INTO admins (callsign, name, pin_hash, role) VALUES (?, ?, ?, ?)').run('OE8YML', 'Admin', pinHash, 'admin');
console.log('  ✓ Default admin OE8YML');

console.log('Seed complete!');
db.close();

